// Table typings are still based on community types which are not that great,
// need to disable no-explicit-any for the plugin file.
/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/ban-types */

import React from 'react';
import { Column } from 'react-table';

import { MultiMeterBarChart } from '../../../charts/meter-bar/multi-meter-bar/MultiMeterBarChart.js';
import { SIZE_8 } from '../../../charts/meter-bar/shared/types/default.js';
import { MeterBarChart } from '../../../charts/meter-bar/single-meter-bar/MeterBarChart.js';
import type {
  MeterbarColumnConfig,
  CompareRows,
  ColumnType,
} from '../../types/shared-table-types.js';

type Alignment = 'left' | 'center' | 'right';

type ExtendedColumn<D extends {}> = Column<D> & {
  sortType?: CompareRows;
  columnType?: ColumnType;
  alignment?: Alignment;
  columns?: ExtendedColumn<D>[];
  config: D;
  Cell?: any;
  disableSortBy?: boolean;
};

export function meterBarChart(
  value: number | { name: string; value: number; color?: string }[],
  column: ExtendedColumn<MeterbarColumnConfig>,
): JSX.Element {
  // simple MeterBar
  if (typeof value === 'number') {
    return (
      <MeterBarChart
        value={value}
        min={column.config?.min}
        max={column.config?.max}
        color={column.config?.color as string}
        size={SIZE_8}
      >
        {column.config?.showTooltip && <MeterBarChart.Tooltip />}
        {column.config?.thresholds && (
          <MeterBarChart.Thresholds>
            {column.config?.thresholds?.map((threshold) => (
              <MeterBarChart.Threshold
                key={`threshold-${threshold.color}-${threshold.value}`}
                name={threshold.name}
                color={threshold.color}
                value={threshold.value}
              />
            ))}
          </MeterBarChart.Thresholds>
        )}
      </MeterBarChart>
    );
  } else {
    const isMultiMeterData =
      Array.isArray(value) &&
      value.every(
        (item) =>
          typeof item === 'object' &&
          typeof item.name === 'string' &&
          typeof item.value === 'number' &&
          (typeof item.color === 'undefined' || typeof item.color === 'string'),
      );
    if (!isMultiMeterData) {
      // eslint-disable-next-line no-console
      console.warn('Not valid meter chart data.');
    }

    // MultiMeterBar
    return (
      <MultiMeterBarChart
        size={'size8'}
        min={column.config?.min}
        max={column.config?.max}
        colorPalette={column.config?.colorPalette || 'categorical'}
      >
        {
          // only if this is multi meter data render segments
          isMultiMeterData &&
            value.map((data) => (
              <MultiMeterBarChart.Segment
                key={`${data.name}-${data.value}`}
                name={data.name}
                value={data.value}
                color={data?.color}
              />
            ))
        }
        <MeterBarChart.Tooltip />
        {column.config?.showTooltip && (
          <MultiMeterBarChart.Tooltip variant={'shared'} />
        )}
      </MultiMeterBarChart>
    );
  }
}
